#include "GameplayAnimation3D.h"
#include <cmath>

using namespace Aevrynd;
namespace GameplayLab {
GameplayAnimation3D::GameplayAnimation3D(){skeleton_.joints.resize(6);skeleton_.joints[0].parent=-1;for(int i=1;i<6;++i)skeleton_.joints[i].parent=0;skeleton_.joints[1].bindTransform.translation={0,1,0};skeleton_.joints[2].bindTransform.translation={-.35f,.8f,0};skeleton_.joints[3].bindTransform.translation={.35f,.8f,0};skeleton_.joints[4].bindTransform.translation={-.2f,0,0};skeleton_.joints[5].bindTransform.translation={.2f,0,0};Evaluate();}
void GameplayAnimation3D::SetState(AnimationState3D state,bool restart){if(state_!=state||restart){state_=state;time_=0;Evaluate();}}
void GameplayAnimation3D::Tick(float deltaTime){time_+=Clamp(deltaTime,0,.1f);Evaluate();}
void GameplayAnimation3D::Evaluate(){pose_.localTransforms.resize(skeleton_.joints.size());for(std::size_t i=0;i<skeleton_.joints.size();++i)pose_.localTransforms[i]=skeleton_.joints[i].bindTransform;const float wave=std::sin(time_*8.f),fast=std::sin(time_*13.f);switch(state_){case AnimationState3D::Idle:pose_.localTransforms[1].translation.y+=std::sin(time_*2.f)*.025f;break;case AnimationState3D::Walk:pose_.localTransforms[2].rotation.x=wave*.45f;pose_.localTransforms[3].rotation.x=-wave*.45f;pose_.localTransforms[4].rotation.x=-wave*.55f;pose_.localTransforms[5].rotation.x=wave*.55f;break;case AnimationState3D::Run:pose_.localTransforms[2].rotation.x=fast*.8f;pose_.localTransforms[3].rotation.x=-fast*.8f;pose_.localTransforms[4].rotation.x=-fast;pose_.localTransforms[5].rotation.x=fast;break;case AnimationState3D::Crouch:pose_.localTransforms[0].translation.y=-.45f;pose_.localTransforms[1].rotation.x=.3f;break;case AnimationState3D::Jump:pose_.localTransforms[0].translation.y=.25f;pose_.localTransforms[4].rotation.x=-.55f;pose_.localTransforms[5].rotation.x=-.55f;break;case AnimationState3D::Fall:pose_.localTransforms[2].rotation.z=-.75f;pose_.localTransforms[3].rotation.z=.75f;break;case AnimationState3D::Attack1:case AnimationState3D::Attack2:case AnimationState3D::Attack3:pose_.localTransforms[state_==AnimationState3D::Attack2?2:3].rotation.x=-1.2f+wave*.25f;pose_.localTransforms[0].rotation.y=state_==AnimationState3D::Attack3?wave*.8f:.25f;break;case AnimationState3D::Hit:pose_.localTransforms[1].rotation.x=-.5f;break;case AnimationState3D::Death:pose_.localTransforms[0].rotation.z=1.45f;pose_.localTransforms[0].translation.y=-.75f;break;}BuildAnimationPoseGlobalMatrices3D(skeleton_,pose_);}
}
